-- South Korea: milestones + English translations. Generated in the
-- same shape as new_country_scaffold.py's output; INSERT OR IGNORE
-- throughout (idempotent). Unlike every clearance-model mandate built
-- this session (Jordan, Israel, Egypt, Saudi, UAE, Oman), South
-- Korea's e-Tax Invoice system is a post-issuance real-time-reporting
-- model: the invoice is valid immediately on delivery to the buyer,
-- with no tax-authority clearance step before that -- it only needs
-- to reach the NTS by the next day. The mandate has been in force for
-- corporations since 2011 and has been phased down to individual
-- entrepreneurs via a shrinking revenue threshold ever since, most
-- recently to KRW 80 million in July 2024 -- the lowest ever. Sourced
-- from Sovos's dedicated e-Tax Invoice history page and VATupdate's
-- July 2026 country booklet, which independently agree on the full
-- threshold-reduction chronology; Voxel Group and Storecove corroborate
-- the more recent (2022-2023) steps.

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence, mandate_scope) SELECT 'kr-corporate-mandate-2011', id, '2011-01-01', 1, 'https://sovos.com/vat/tax-rules/electronic-tax-invoices-south-korea/', 0, '[]', NULL, 'b2b' FROM countries WHERE code = 'KR';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('kr-corporate-mandate-2011', 'en', 'e-Tax Invoice becomes mandatory for all corporations', 'South Korea required all corporate taxpayers to issue Value-Added Tax invoices electronically and report them to the National Tax Service (NTS) by the next business day. This is a post-issuance reporting model, not a clearance model: the invoice takes legal effect once delivered to the buyer, and next-day transmission to the NTS is a separate reporting obligation rather than a precondition for the invoice''s validity.', '["No action required today -- this milestone is historical context for how long South Korea''s e-Tax Invoice system has already been in force", "If your business is a Korean corporation, e-invoicing has already been mandatory for you since 2011 regardless of size"]');

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence, mandate_scope) SELECT 'kr-individual-2012', id, '2012-01-01', 0, 'https://sovos.com/vat/tax-rules/electronic-tax-invoices-south-korea/', 0, '[]', NULL, 'b2b' FROM countries WHERE code = 'KR';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('kr-individual-2012', 'en', 'Individual entrepreneurs above KRW 1 billion brought into scope', 'The e-Tax Invoice mandate extended beyond corporations to individual entrepreneurs (sole proprietors) with annual supply value exceeding KRW 1 billion -- the first of what would become a series of threshold reductions steadily widening the mandate''s reach over the following decade.', '["Historical context only -- see the more recent threshold reductions below for the figure that matters today"]');

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence, mandate_scope) SELECT 'kr-threshold-300m-2014', id, '2014-07-01', 0, 'https://sovos.com/vat/tax-rules/electronic-tax-invoices-south-korea/', 0, '[]', NULL, 'b2b' FROM countries WHERE code = 'KR';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('kr-threshold-300m-2014', 'en', 'Individual entrepreneur threshold lowered to KRW 300 million', 'The revenue threshold bringing individual entrepreneurs into the e-Tax Invoice mandate fell from KRW 1 billion to KRW 300 million, the first of several reductions that would continue through the 2020s.', '["Historical context only -- see the more recent threshold reductions below for the figure that matters today"]');

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence, mandate_scope) SELECT 'kr-threshold-200m-2022', id, '2022-07-01', 0, 'https://sovos.com/vat/tax-rules/electronic-tax-invoices-south-korea/', 1, '[{"label": "NTS Hometax -- e-Tax Invoice system", "url": "https://www.hometax.go.kr"}]', NULL, 'b2b' FROM countries WHERE code = 'KR';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('kr-threshold-200m-2022', 'en', 'Individual entrepreneur threshold lowered to KRW 200 million', 'The revenue threshold fell again, from KRW 300 million to KRW 200 million, bringing a wider band of individual entrepreneurs into the mandatory e-Tax Invoice system -- part of a sustained multi-year push toward near-universal coverage.', '["If your annual supply value as an individual entrepreneur exceeds KRW 200 million, confirm you are issuing e-Tax Invoices through NTS Hometax or an equivalent channel", "Businesses below this threshold may still participate voluntarily"]');

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence, mandate_scope) SELECT 'kr-threshold-100m-2023', id, '2023-07-01', 0, 'https://www.storecove.com/blog/en/e-invoicing-in-south-korea-regulations/', 1, '[{"label": "NTS Hometax -- e-Tax Invoice system", "url": "https://www.hometax.go.kr"}]', NULL, 'b2b' FROM countries WHERE code = 'KR';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('kr-threshold-100m-2023', 'en', 'Threshold falls to KRW 100 million; self-billing invoices introduced', 'The individual-entrepreneur threshold fell to KRW 100 million, and the NTS introduced self-billing invoices: where a supplier is unable to issue an e-Tax Invoice, the buyer may create one instead for VAT-taxable supplies, subject to confirmation by a district tax office.', '["Confirm whether your annual supply value now exceeds KRW 100 million and, if so, that you are issuing e-Tax Invoices", "If a supplier of yours cannot issue an e-Tax Invoice, check whether self-billing is available to you as the buyer"]');

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence, mandate_scope) SELECT 'kr-threshold-80m-2024', id, '2024-07-01', 0, 'https://sovos.com/vat/tax-rules/electronic-tax-invoices-south-korea/', 1, '[{"label": "NTS Hometax -- e-Tax Invoice system", "url": "https://www.hometax.go.kr"}]', NULL, 'b2b' FROM countries WHERE code = 'KR';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('kr-threshold-80m-2024', 'en', 'Threshold falls to KRW 80 million -- the lowest yet', 'The individual-entrepreneur threshold fell again to KRW 80 million in prior-year supply, the lowest level since the mandate first extended beyond corporations in 2012. This is the current threshold as of this tracker''s last update; further reductions are widely expected to continue the trend toward universal coverage, though no further specific date has been legislated yet.', '["Check your prior-year supply value against the current KRW 80 million threshold, not an older figure you may remember from a few years ago", "If you are close to the threshold, plan for e-Tax Invoice issuance now rather than waiting for the next reduction to catch you by surprise"]');
